from datetime import date, timedelta
from itertools import islice
import calendar

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
_LIMIT_YEAR = 3000


def _daily(start, k):
    d = start
    while d.year < _LIMIT_YEAR:
        yield d
        d += timedelta(days=k)


def _weekly(start, k, days):
    monday = start - timedelta(days=start.weekday())
    wds = sorted(_WD[x] for x in days)
    w = 0
    while True:
        base = monday + timedelta(weeks=w * k)
        if base.year >= _LIMIT_YEAR:
            return
        for wd in wds:
            d = base + timedelta(days=wd)
            if d >= start:
                yield d
        w += 1


def _monthly_day(start, k, day):
    base = start.year * 12 + start.month - 1
    m = 0
    while True:
        y, mo0 = divmod(base + m * k, 12)
        if y >= _LIMIT_YEAR:
            return
        mo = mo0 + 1
        ndays = calendar.monthrange(y, mo)[1]
        if day == -1:
            dd = ndays
        elif day <= ndays:
            dd = day
        else:
            dd = None
        if dd is not None:
            d = date(y, mo, dd)
            if d >= start:
                yield d
        m += 1


def _monthly_nth(start, k, n, wd):
    base = start.year * 12 + start.month - 1
    m = 0
    while True:
        y, mo0 = divmod(base + m * k, 12)
        if y >= _LIMIT_YEAR:
            return
        mo = mo0 + 1
        ndays = calendar.monthrange(y, mo)[1]
        if n > 0:
            first = date(y, mo, 1)
            offset = (wd - first.weekday()) % 7
            d = first + timedelta(days=offset + 7 * (n - 1))
            if d.month != mo:
                d = None
        else:
            last = date(y, mo, ndays)
            d = last - timedelta(days=(last.weekday() - wd) % 7)
        if d is not None and d >= start:
            yield d
        m += 1


def _yearly(start, k, mm, dd):
    m = 0
    while True:
        y = start.year + m * k
        if y >= _LIMIT_YEAR:
            return
        try:
            d = date(y, mm, dd)
        except ValueError:
            d = None
        if d is not None and d >= start:
            yield d
        m += 1


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    tokens = rule.split(" ")
    kind = tokens[0]

    if kind == "DAILY":
        gen = _daily(s, int(tokens[1]))
    elif kind == "WEEKLY":
        gen = _weekly(s, int(tokens[1]), tokens[2].split(","))
    elif kind == "MONTHLY":
        k = int(tokens[1])
        if len(tokens) == 3:
            gen = _monthly_day(s, k, int(tokens[2]))
        else:
            gen = _monthly_nth(s, k, int(tokens[2]), _WD[tokens[3]])
    elif kind == "YEARLY":
        mm, dd = map(int, tokens[2].split("-"))
        gen = _yearly(s, int(tokens[1]), mm, dd)
    else:
        raise ValueError(f"Unknown rule: {rule}")

    return [d.isoformat() for d in islice(gen, count)]
